      "before": "not booted, because a boot writes /x.db at the filesystem root. Read from the built module: config.filename '//x.db' in dev and prod, while the runtime host answers 'x.db'.",
      "after": "dev and production: 'Server is ready', 'Driver: SqlDriver(better-sqlite3) → sqlite://x.db', created ./x.db in the probe directory under the scratch dir, never at /; built module: filename 'x.db', equal to the runtime host's"
    },
    "redis_wasm_db": {
      "before": "dev and production: 'Server is ready', 'Driver: SqliteWasmDriver → redis://h/x.wasm.db', created ./redis:/h/x.wasm.db",
      "after": "dev and production: exit 1, the same sentence naming \"redis://\", no file"
